import { test, expect } from "@playwright/test";

test("Search for products by term", async ({ page }) => {
  await page.goto("/");

  await page.getByTestId("search-input").fill("Orbit");
  await page.getByTestId("search-button").click();

  const resultsContainer = page.getByTestId("search-results");
  await expect(resultsContainer).toBeVisible();

  const productTiles = resultsContainer.getByTestId("product-tile");
  const count = await productTiles.count();
  
  expect(count).toBeGreaterThan(0);

  for (let i = 0; i < count; i++) {
    const title = await productTiles.nth(i).getByTestId("product-card-title").textContent();
    expect(title?.toLowerCase()).toContain("orbit");
  }
});
